WITH cleaned AS (SELECT id, category, brand, price, cost, launch_date, tags, supplier_id, LENGTH(brand) AS brand_length, COALESCE(brand, 'UNKNOWN') AS brand_clean FROM products WHERE launch_date > TO_DATE('2023-05-13') AND brand IS DISTINCT FROM 'Stark') SELECT supplier_id, DATE_TRUNC('WEEK', launch_date) AS week_start, STDDEV_SAMP(price) AS price_stddev, COUNT(*) FILTER (WHERE brand = 'Initech') AS initech_rows, STDDEV_SAMP(price) AS price_stddev_2, SUM(CASE WHEN brand = 'Globex' THEN brand_length ELSE 0 END) AS globex_brand_length, ROUND(SUM(brand_length) / NULLIF(COUNT(CASE WHEN brand = 'Initech' THEN 1 END), 0), 2) AS brand_length_per_initech, STDDEV_SAMP(price) AS price_stddev_3 FROM cleaned GROUP BY 1, 2 ORDER BY week_start DESC NULLS FIRST;
